export const GLOSSARY_SHARD = Object.freeze({"market-capitalization":{"slug":"market-capitalization","cat":"basics","en":"Market capitalization","contentLocale":"es","term":"Capitalización de mercado (market cap)","aka":["market cap","capitalización","cap de mercado"],"short":"La capitalización de mercado (market cap) de una criptomoneda es el precio de una unidad multiplicado por su suministro circulante, y sirve para comparar el tamaño de distintos proyectos.","body":[["El precio por unidad no dice nada por sí solo. Un token a 0,01 dólares puede valer más en conjunto que otro a 100 dólares si tiene muchísimas más unidades en circulación. La capitalización resuelve eso: precio × ",["suministro circulante","circulating-supply"],"."],["Los rankings de criptomonedas se ordenan por market cap. Las de mayor capitalización suelen tener más ",["liquidez","liquidity"]," y moverse algo menos que las pequeñas, aunque en cripto todo es volátil. También se habla de la capitalización total del mercado, que suma todas las criptomonedas."],["Ten en cuenta sus límites: solo cuenta el suministro circulante, no los tokens bloqueados que saldrán después, y en tokens con poco volumen el precio puede ser fácil de mover. Por eso conviene mirarla junto a la ",["valoración totalmente diluida (FDV)","fully-diluted-valuation"]," y el volumen diario."]],"example":["Supón dos tokens. El token A cuesta 0,50 ",["USDT","usdt"]," y tiene 2.000 millones de unidades en circulación: su market cap es 1.000 millones de USDT. El token B cuesta 40 USDT y tiene 10 millones en circulación: su market cap es 400 millones. Aunque B parece \"caro\", A es 2,5 veces más grande. Para que A llegue a 5 USDT, su capitalización tendría que pasar a 10.000 millones, algo que conviene tener presente antes de asumir que un precio bajo deja mucho margen."],"mistakes":["Pensar que un token barato por unidad tiene más potencial solo por su precio.","Comparar capitalizaciones sin mirar cuánto suministro queda por desbloquear.","Confundir capitalización de mercado con el dinero que realmente ha entrado en el proyecto."],"faq":[{"q":"¿Cómo se calcula la capitalización de mercado?","a":"Se multiplica el precio actual por el suministro circulante. Si un token vale 2 USDT y circulan 50 millones, su market cap es 100 millones de USDT."},{"q":"¿Una capitalización alta significa que es seguro?","a":"No. Indica tamaño, no seguridad. Un proyecto grande también puede caer con fuerza o tener riesgos técnicos y regulatorios."}],"title":"¿Qué es la capitalización de mercado (market cap)?","description":"Qué es la capitalización de mercado de una criptomoneda, cómo se calcula con el suministro circulante y por qué el precio por unidad engaña.","related":[["fully-diluted-valuation","Valoración totalmente diluida (FDV)","La valoración totalmente diluida (FDV) es el precio actual de un token multiplicado por su suministro máximo o total, es decir, lo que valdría el proyecto si todos los tokens ya estuvieran en circulación."],["circulating-supply","Suministro circulante (circulating supply)","El suministro circulante es la cantidad de unidades de una criptomoneda que ya están disponibles y pueden negociarse en el mercado, sin contar las bloqueadas, reservadas o quemadas."],["trading-volume","Volumen de trading","El volumen de trading es el valor total de un activo que se ha comprado y vendido en un periodo concreto, normalmente las últimas 24 horas."],["tokenomics","Tokenomics (tokenomía)","Tokenomics es el diseño económico de un token: cuántos existen, cómo se reparten, cuándo se liberan, para qué se usan y qué mecanismos aumentan o reducen su suministro."],["altcoin","Altcoin","Una altcoin es cualquier criptomoneda distinta de Bitcoin, desde grandes redes como Ethereum o Solana hasta tokens pequeños y memecoins con poca liquidez."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"market-maker":{"slug":"market-maker","cat":"trading","en":"Market maker","contentLocale":"es","term":"Market maker (creador de mercado)","aka":["creador de mercado","market maker","proveedor de liquidez"],"short":"Un market maker o creador de mercado es un participante que publica a la vez órdenes de compra y de venta en un mercado para aportar liquidez y ganar con el spread.","body":["El creador de mercado mantiene órdenes límite a ambos lados del libro: compra un poco por debajo del precio y vende un poco por encima. Cada vez que otro trader cruza esas órdenes, el market maker gana la diferencia, aunque asume el riesgo de quedarse con inventario si el precio se mueve en contra.",["En cripto hay firmas profesionales que hacen market making en exchanges centralizados, a menudo con acuerdos de comisión especiales. Los proyectos nuevos también contratan market makers para que su token tenga ",["liquidez","liquidity"]," al listarse. En ",["finanzas descentralizadas","defi"],", el papel lo cumplen los creadores de mercado automatizados (",["AMM","amm"],") y los proveedores de liquidez de los pools."],["Para ti, un buen market maker significa spreads estrechos y menos ",["deslizamiento","slippage"],". Pero cualquier trader que deja órdenes límite en el libro actúa como maker en esa operación concreta, aunque no sea una firma profesional."]],"example":["Supón que un market maker cotiza ",["BTC","bitcoin"]," con compra a 59.990 y venta a 60.010 ",["USDT","usdt"],", 0,5 BTC por lado. Un trader vende 0,5 BTC a mercado y otro compra 0,5 BTC poco después. El market maker compró a 59.990 y vendió a 60.010: ganó 20 USDT por BTC, es decir, 10 USDT por 0,5 BTC, más posibles reembolsos de comisión maker. Si el precio hubiera caído a 59.800 antes de vender, habría perdido 95 USDT en ese inventario."],"mistakes":["Pensar que el market maker siempre gana; también pierde cuando el precio se mueve fuerte contra su inventario.","Confundir market maker con la comisión maker que paga cualquier usuario que deja una orden en el libro.","Suponer que todo movimiento brusco es manipulación del market maker sin más pruebas."],"faq":[{"q":"¿Qué hace un market maker en cripto?","a":"Publica órdenes de compra y venta continuas para que siempre haya contrapartida. Gana con el spread y con incentivos del exchange, y asume el riesgo de inventario."},{"q":"¿Los market makers manipulan el precio?","a":"Su función legítima es dar liquidez. Algunos acuerdos opacos con proyectos pequeños han generado críticas, así que conviene vigilar tokens con liquidez muy concentrada."}],"title":"¿Qué es un market maker en cripto? Significado","description":"Qué hace un creador de mercado, cómo gana con el spread, qué riesgos asume y por qué importa para tu deslizamiento.","related":[["liquidity","Liquidez","La liquidez es la facilidad con la que puedes comprar o vender un activo rápidamente, en la cantidad que quieres, sin mover mucho su precio."],["bid-ask-spread","Spread (diferencial de compra-venta)","El spread o diferencial de compra-venta es la diferencia entre el mejor precio al que alguien quiere comprar (bid) y el mejor precio al que alguien quiere vender (ask) un activo en un momento dado."],["maker-taker-fees","Comisiones maker y taker","Las comisiones maker y taker son las dos tarifas que cobra un exchange según tu orden añada liquidez al libro de órdenes (maker) o la retire al ejecutarse de inmediato (taker)."],["order-book","Libro de órdenes (order book)","El libro de órdenes (order book) es la lista en tiempo real de todas las órdenes de compra (bids) y de venta (asks) pendientes para un par, ordenadas por precio, que muestra a qué precios hay compradores y vendedores y en qué cantidad."],["amm","Creador de mercado automatizado (AMM)","Un creador de mercado automatizado (AMM) es un contrato inteligente que fija el precio de un intercambio con una fórmula basada en las reservas de un pool de liquidez, en lugar de emparejar órdenes de compradores y vendedores."]],"lesson":null,"coin":null,"tool":null,"cta":false},"risk-reward-ratio":{"slug":"risk-reward-ratio","cat":"trading","en":"Risk-reward ratio","contentLocale":"es","term":"Relación riesgo-beneficio","aka":["ratio riesgo-beneficio","risk-reward","R:R","relación riesgo/recompensa"],"short":"La relación riesgo-beneficio compara cuánto puedes perder en una operación hasta tu stop loss con cuánto puedes ganar hasta tu take profit.","body":[["Se calcula con la distancia entre la entrada y el ",["stop loss","stop-loss"]," (riesgo) y la distancia entre la entrada y el objetivo (beneficio). Si arriesgas 100 para intentar ganar 300, la relación es 1:3. Cuanto mayor es el beneficio frente al riesgo, menos operaciones necesitas acertar para no perder dinero."],"Esta relación debe leerse junto con la tasa de acierto. Con 1:1 necesitas ganar más de la mitad de las operaciones para tener beneficio, sin contar comisiones. Con 1:3, en teoría te basta con acertar algo más de una de cada cuatro. Un objetivo muy lejano, en cambio, se alcanza con menos frecuencia.",["Calcula la relación antes de entrar, con niveles realistas basados en soportes, resistencias y ",["volatilidad","volatility"],". Incluye comisiones y, en futuros, la ",["tasa de financiación","funding-rate"]," si mantendrás la posición varios días. Una ",["orden OCO","oco-order"]," te permite fijar stop y objetivo a la vez."]],"example":["Compras BNB en 600 ",["USDT","usdt"]," con stop loss en 580 y objetivo en 660. Arriesgas 20 USDT por unidad para ganar 60: relación 1:3. Si haces 10 operaciones parecidas y aciertas 3, ganas 3 × 60 = 180 y pierdes 7 × 20 = 140. El resultado neto es +40 USDT por unidad antes de comisiones, aunque fallaste el 70 % de las veces."],"mistakes":["Fijar objetivos irreales solo para que la relación se vea bonita sobre el papel.","Mover el stop loss más lejos cuando el precio se acerca, lo que destruye la relación calculada.","Ignorar comisiones y deslizamiento, que reducen el beneficio real en operaciones cortas."],"faq":[{"q":"¿Cuál es una buena relación riesgo-beneficio?","a":"Muchos traders buscan al menos 1:2, pero depende de tu tasa de acierto. Una estrategia con muchos aciertos puede funcionar con 1:1."},{"q":"¿Cómo se calcula el ratio riesgo-beneficio?","a":"Divide la ganancia potencial (objetivo menos entrada) entre la pérdida potencial (entrada menos stop). Para cortos, invierte las restas."}],"title":"¿Qué es la relación riesgo-beneficio en trading?","description":"Cómo calcular la relación riesgo-beneficio, por qué depende de tu tasa de acierto y cómo usarla antes de abrir una operación.","related":[["position-sizing","Tamaño de posición","El tamaño de posición es la cantidad de capital que asignas a una operación, calculada para que, si toca tu stop loss, pierdas solo un porcentaje fijo de tu cuenta."],["stop-loss","Stop loss (orden de stop)","Un stop loss es una orden que cierra automáticamente tu posición cuando el precio llega a un nivel que has fijado, para limitar la pérdida si el mercado va en tu contra."],["take-profit","Take profit (toma de beneficios)","Un take profit (TP) es una orden que cierra automáticamente tu posición, total o parcialmente, cuando el precio alcanza un objetivo de ganancia que has fijado de antemano."],["oco-order","Orden OCO (una cancela la otra)","Una orden OCO (one-cancels-the-other, una cancela la otra) agrupa dos órdenes, normalmente un take profit y un stop loss, de forma que cuando una se ejecuta el exchange cancela automáticamente la otra."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Decide cuánto podrías perder antes de decidir cuánto comprar"},"coin":null,"tool":null,"cta":false},"futures-contract":{"slug":"futures-contract","cat":"derivatives","en":"Futures contract","contentLocale":"es","term":"Contrato de futuros","aka":["futuros","futuros cripto","futures"],"short":"Un contrato de futuros es un acuerdo para comprar o vender un activo a un precio fijado hoy, con liquidación en una fecha futura o, en el caso de los perpetuos, sin fecha de vencimiento.","body":[["Con un futuro no compras la moneda en sí, sino un contrato cuyo valor sigue su precio. Puedes abrir una posición larga si crees que el precio subirá o una ",["posición corta","short-selling"]," si crees que bajará. En cripto casi todos los futuros se liquidan en efectivo (",["USDT","usdt"],", ",["USDC","usdc"]," o la propia moneda), sin entrega física del activo."],["Hay dos grandes familias: los ",["futuros con vencimiento","delivery-futures"]," o de entrega, que expiran en una fecha concreta (por ejemplo trimestral), y los ",["futuros perpetuos","perpetual-futures"],", que no vencen y usan una ",["tasa de financiación","funding-rate"]," para mantenerse cerca del precio spot. También se distinguen por el margen: futuros con margen en USDT (lineales) o con margen en la moneda (inversos)."],"Los futuros permiten usar apalancamiento y cubrir carteras, pero el apalancamiento multiplica pérdidas y ganancias por igual. Si el margen no alcanza, la posición se liquida. Antes de operar revisa la especificación del contrato en tu exchange: tamaño, vencimiento, margen de mantenimiento y comisiones."],"example":"Abres un largo de 1 BTC en un futuro trimestral a 60.000 USDT con apalancamiento 5x, así que aportas 12.000 USDT de margen. Al vencimiento el precio de liquidación es 63.000 USDT. Tu ganancia es 63.000 − 60.000 = 3.000 USDT, un 25 % sobre el margen, antes de comisiones. Si en cambio el precio hubiera vencido en 57.000, habrías perdido 3.000 USDT, también un 25 % del margen.","mistakes":["Pensar que al comprar un futuro tienes la criptomoneda y puedes retirarla a tu billetera.","Usar apalancamiento alto sin calcular a qué precio se liquida la posición.","Confundir futuros con vencimiento y perpetuos, que tienen costes y comportamientos distintos."],"faq":[{"q":"¿Qué diferencia hay entre spot y futuros?","a":"En spot compras la moneda y es tuya. En futuros operas un contrato sobre su precio, puedes ir en corto y usar apalancamiento, pero no posees el activo."},{"q":"¿Los futuros cripto tienen fecha de vencimiento?","a":"Los futuros de entrega sí, por ejemplo trimestral. Los perpetuos no vencen nunca y se mantienen alineados con el spot mediante la tasa de financiación."}],"title":"¿Qué es un contrato de futuros en cripto?","description":"Qué es un contrato de futuros cripto, en qué se diferencia del spot y qué tipos existen: con vencimiento, perpetuos, lineales e inversos.","related":[["perpetual-futures","Futuros perpetuos (perps)","Los futuros perpetuos son contratos de futuros sin fecha de vencimiento que siguen el precio spot gracias a pagos periódicos entre largos y cortos llamados tasa de financiación."],["delivery-futures","Futuros de entrega (trimestrales)","Los futuros de entrega o con vencimiento son contratos que expiran en una fecha fija, por ejemplo cada trimestre, y se liquidan a un precio de referencia ese día."],["leverage","Apalancamiento","El apalancamiento es usar capital prestado para abrir una posición mayor que tu margen, de modo que las ganancias y las pérdidas se multiplican en la misma proporción."],["margin-trading","Trading con margen","El trading con margen consiste en pedir prestados fondos al exchange para comprar o vender un activo por más de lo que tienes, usando tus fondos como garantía."],["hedging","Cobertura (hedging)","La cobertura o hedging es abrir una posición que gana cuando otra pierde, para reducir el riesgo de una cartera frente a movimientos de precio sin necesidad de venderla."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futuros: no estás comprando lo mismo"},"coin":null,"tool":"/topics/derivatives","cta":true},"cross-margin":{"slug":"cross-margin","cat":"derivatives","en":"Cross margin","contentLocale":"es","term":"Margen cruzado","aka":["cross margin","modo cruzado","margen compartido"],"short":"El margen cruzado es un modo en el que todo el saldo disponible de tu cuenta de futuros o margen sirve de garantía compartida para todas tus posiciones abiertas.","body":[["En modo cruzado no asignas un margen fijo a cada posición. El exchange suma tu saldo, las ganancias y pérdidas no realizadas de todas las posiciones y los requisitos de ",["margen de mantenimiento","maintenance-margin"],". Mientras el total cubra el mínimo, ninguna posición se liquida."],["La ventaja es que las posiciones tienen más colchón: el saldo libre y las ganancias de una operación ayudan a sostener otra que va en contra. Esto aleja el ",["precio de liquidación","liquidation-price"]," y es útil si tienes posiciones que se compensan entre sí."],["El riesgo es que una sola posición mala puede consumir toda la cuenta. Si el precio sigue en contra, la ",["liquidación","liquidation"]," puede llevarse el saldo completo, no solo el ",["margen inicial","initial-margin"],". Por eso muchos traders usan margen cruzado solo con un saldo de futuros limitado, separado del resto de sus fondos."]],"example":["Tienes 5.000 ",["USDT","usdt"]," en la cuenta de futuros y abres un largo de 0,5 ",["BTC","bitcoin"]," a 60.000 (nocional 30.000) con 10x. En modo aislado con 3.000 de margen y un mantenimiento cercano a 150 USDT, la liquidación llegaría tras perder unos 2.850, hacia 54.300. En modo cruzado, los 5.000 respaldan la posición: puedes perder unos 4.850 antes de la liquidación, hacia 50.300. Más colchón, pero si llega, pierdes casi toda la cuenta."],"mistakes":["Tener todo el capital en la cuenta de futuros en modo cruzado y arriesgarlo en una sola operación.","Creer que el margen inicial mostrado es lo máximo que puedes perder en modo cruzado.","Abrir muchas posiciones correlacionadas pensando que se compensan cuando en realidad se mueven igual."],"faq":[{"q":"¿Margen cruzado o aislado para principiantes?","a":"El aislado es más fácil de controlar porque limita la pérdida de cada posición. El cruzado exige vigilar el riesgo de toda la cuenta."},{"q":"¿Puedo perder todo mi saldo con margen cruzado?","a":"Sí. Si las pérdidas siguen creciendo, la liquidación usa todo el saldo de la cuenta de futuros como garantía."}],"title":"¿Qué es el margen cruzado en futuros cripto?","description":"Qué es el margen cruzado, cómo comparte el saldo entre posiciones, por qué aleja la liquidación y qué riesgo añade a tu cuenta.","related":[["isolated-margin","Margen aislado","El margen aislado es un modo en el que cada posición tiene su propio margen asignado, de forma que si se liquida solo pierdes ese margen y no el resto del saldo."],["portfolio-margin","Margen de cartera (portfolio margin)","El margen de cartera es un modo que calcula la garantía necesaria según el riesgo neto de todas tus posiciones juntas, de modo que las coberturas reducen el margen requerido."],["unified-trading-account","Cuenta unificada de trading (UTA)","Una cuenta unificada de trading es un tipo de cuenta de exchange que reúne spot, margen y derivados en un solo saldo, de modo que tus activos sirven como margen común para todas las posiciones."],["liquidation","Liquidación","La liquidación es el cierre forzoso de una posición apalancada por parte del exchange cuando tu margen ya no cubre el margen de mantenimiento exigido."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"Margen cruzado: por qué una pérdida puede golpear tus otras posiciones"},"coin":null,"tool":null,"cta":false},"long-and-short":{"slug":"long-and-short","cat":"derivatives","en":"Long and short positions","contentLocale":"es","term":"Posiciones largas y cortas (long y short)","aka":["long","short","ir en largo","ir en corto"],"short":"Una posición larga (long) gana cuando el precio sube y una posición corta (short) gana cuando el precio baja; son las dos direcciones básicas en las que puedes operar un activo.","body":["Ir en largo significa comprar, o abrir un contrato de compra, esperando vender más caro. En spot solo puedes ir en largo: compras la moneda y la vendes después. Ir en corto significa vender primero, esperando recomprar más barato. Para eso necesitas futuros, margen o un préstamo del activo.",["La pérdida de un largo sin ",["apalancamiento","leverage"]," está limitada a lo que invertiste, porque el precio no baja de cero. En un corto, la pérdida teórica no tiene límite, porque el precio puede subir indefinidamente. Con apalancamiento ambas direcciones pueden liquidarse."],["En ",["futuros perpetuos","perpetual-futures"],", los largos y cortos también se pagan entre sí la ",["tasa de financiación","funding-rate"],". Los cortos sirven tanto para especular con caídas como para cubrir una cartera spot frente a bajadas."]],"example":[["ETH","ethereum"]," cotiza a 3.000 ",["USDT","usdt"],". Ana abre un largo de 1 ETH y Luis abre un corto de 1 ETH en el mismo perpetuo. Si ETH sube a 3.300, Ana gana 300 USDT y Luis pierde 300. Si en cambio ETH baja a 2.700, Luis gana 300 y Ana pierde 300. Antes de comisiones y financiación, lo que gana un lado es lo que pierde el otro."],"mistakes":["Creer que en spot puedes beneficiarte de una caída sin usar futuros o margen.","Abrir cortos sin stop loss, olvidando que la pérdida no tiene techo.","Pensar que los largos siempre son más seguros aunque se usen con mucho apalancamiento."],"faq":[{"q":"¿Qué significa estar long en cripto?","a":"Tener una posición que gana si el precio sube, ya sea comprando la moneda en spot o abriendo un contrato largo de futuros."},{"q":"¿Qué significa hacer short?","a":"Abrir una posición que gana si el precio baja, vendiendo primero para recomprar más barato, normalmente con futuros o margen."}],"title":"¿Qué es long y short en cripto? Significado","description":"Qué significan las posiciones largas y cortas, cómo ganan o pierden según el precio y por qué el corto tiene riesgo ilimitado.","related":[["short-selling","Venta en corto","La venta en corto es vender un activo que no tienes, normalmente prestado o mediante un contrato, para recomprarlo más tarde a un precio menor y quedarte con la diferencia."],["perpetual-futures","Futuros perpetuos (perps)","Los futuros perpetuos son contratos de futuros sin fecha de vencimiento que siguen el precio spot gracias a pagos periódicos entre largos y cortos llamados tasa de financiación."],["leverage","Apalancamiento","El apalancamiento es usar capital prestado para abrir una posición mayor que tu margen, de modo que las ganancias y las pérdidas se multiplican en la misma proporción."],["long-short-ratio","Ratio largos/cortos","El ratio largos/cortos compara cuántas cuentas o posiciones están en largo frente a cuántas están en corto en un mercado de futuros, y se usa como indicador del sentimiento."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futuros: no estás comprando lo mismo"},"coin":null,"tool":null,"cta":true},"short-selling":{"slug":"short-selling","cat":"derivatives","en":"Short selling","contentLocale":"es","term":"Venta en corto","aka":["short selling","vender en corto","shortear","posición corta"],"short":"La venta en corto es vender un activo que no tienes, normalmente prestado o mediante un contrato, para recomprarlo más tarde a un precio menor y quedarte con la diferencia.","body":[["En el ",["margen spot","margin-trading"],", el exchange te presta la moneda, tú la vendes y más tarde la recompras para devolverla, pagando intereses por el préstamo. En futuros no hay préstamo explícito: abres directamente un contrato corto, y en ",["perpetuos","perpetual-futures"]," pagas o cobras la ",["tasa de financiación","funding-rate"],"."],["Se usa para especular con caídas o para cubrirse. Por ejemplo, si tienes ",["BTC","bitcoin"]," a largo plazo y temes una bajada temporal, un corto en futuros compensa parte de la pérdida sin vender tus monedas."],["El gran riesgo es que la pérdida no tiene límite teórico: si el precio sube, sigues perdiendo. Las subidas rápidas pueden provocar un ",["short squeeze","short-squeeze"],", en el que muchos cortos son liquidados a la vez y empujan el precio aún más arriba. Usa siempre ",["stop loss","stop-loss"]," y tamaño moderado."]],"example":"Pides prestados 10 SOL en margen spot cuando SOL vale 150 USDT y los vendes por 1.500 USDT. Una semana después SOL baja a 120: recompras 10 SOL por 1.200, devuelves el préstamo y pagas 2 USDT de interés. Ganas 1.500 − 1.200 − 2 = 298 USDT. Si SOL hubiera subido a 190, recomprar costaría 1.900 y perderías 402 USDT, interés incluido.","mistakes":["Abrir un corto sin stop loss porque crees que el activo está caro.","No contar los intereses del préstamo o la tasa de financiación al calcular el resultado.","Hacer corto en tokens con poca oferta en circulación, propensos a subidas bruscas."],"faq":[{"q":"¿Cómo se hace short en criptomonedas?","a":"Con futuros (abriendo un contrato corto) o con margen spot (pidiendo prestada la moneda y vendiéndola). Ambos requieren una cuenta de derivados o margen."},{"q":"¿Cuánto se puede perder con una venta en corto?","a":"En teoría no hay límite, porque el precio puede subir sin techo. En la práctica la liquidación cierra la posición antes, pero puedes perder todo el margen."}],"title":"¿Qué es la venta en corto en cripto?","description":"Qué es vender en corto, cómo se hace con futuros o margen, cómo se calcula el resultado y por qué el riesgo es ilimitado.","related":[["long-and-short","Posiciones largas y cortas (long y short)","Una posición larga (long) gana cuando el precio sube y una posición corta (short) gana cuando el precio baja; son las dos direcciones básicas en las que puedes operar un activo."],["perpetual-futures","Futuros perpetuos (perps)","Los futuros perpetuos son contratos de futuros sin fecha de vencimiento que siguen el precio spot gracias a pagos periódicos entre largos y cortos llamados tasa de financiación."],["margin-trading","Trading con margen","El trading con margen consiste en pedir prestados fondos al exchange para comprar o vender un activo por más de lo que tienes, usando tus fondos como garantía."],["short-squeeze","Short squeeze (estrangulamiento de cortos)","Un short squeeze es una subida rápida del precio provocada porque muchos vendedores en corto se ven obligados a recomprar, por stop loss o liquidación, y esas compras empujan el precio aún más."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Spot vs futuros: no estás comprando lo mismo"},"coin":null,"tool":null,"cta":false},"futures-basis":{"slug":"futures-basis","cat":"derivatives","en":"Futures basis","contentLocale":"es","term":"Base de futuros","aka":["basis","base","prima de futuros"],"short":"La base de futuros es la diferencia entre el precio de un contrato de futuros y el precio spot del mismo activo, y suele expresarse en dólares o en porcentaje anualizado.","body":[["Si el futuro cotiza por encima del spot, la base es positiva y el mercado está en contango. Si cotiza por debajo, la base es negativa (backwardation). En cripto, la base de los ",["futuros trimestrales","delivery-futures"]," suele ser positiva en fases alcistas, porque muchos traders pagan una prima por estar largos con ",["apalancamiento","leverage"],"."],["En los futuros con vencimiento, la base se reduce hasta cero en la fecha de ",["liquidación","liquidation"],", porque el contrato se liquida al ",["precio índice","index-price"],". En los ",["perpetuos","perpetual-futures"],", la diferencia con el índice se corrige continuamente a través de la ",["tasa de financiación","funding-rate"],"."],"Para comparar contratos con distintos vencimientos se usa la base anualizada: porcentaje de base × 365 / días hasta el vencimiento. Los traders de base compran spot y venden el futuro para capturar esa diferencia, con riesgos de ejecución, de margen en la pata corta y de contraparte."],"example":"BTC spot cotiza a 60.000 USDT y el futuro trimestral, a 90 días de vencer, a 61.500. La base es 1.500 USDT, un 2,5 %. Anualizada: 2,5 % × 365 / 90, cerca del 10,1 %. Si compras 1 BTC spot y vendes 1 BTC en el futuro, al vencimiento ambos convergen y capturas 1.500 USDT antes de comisiones, suba o baje el precio.","mistakes":["Comparar bases de contratos con vencimientos distintos sin anualizarlas.","Olvidar que la pata corta en futuros necesita margen y puede liquidarse si el precio sube mucho.","Pensar que la base es siempre positiva; en caídas fuertes puede volverse negativa."],"faq":[{"q":"¿Qué significa que la base sea positiva?","a":"Que el futuro cotiza por encima del spot (contango). Suele reflejar demanda de posiciones largas apalancadas y tiende a cero al vencer."},{"q":"¿Cómo se calcula la base anualizada?","a":"Divide la diferencia entre futuro y spot por el precio spot, multiplica por 365 y divide por los días hasta el vencimiento."}],"title":"¿Qué es la base de futuros? Contango y anualizada","description":"Qué es la base de futuros, qué significan contango y backwardation y cómo calcular la base anualizada con un ejemplo.","related":[["delivery-futures","Futuros de entrega (trimestrales)","Los futuros de entrega o con vencimiento son contratos que expiran en una fecha fija, por ejemplo cada trimestre, y se liquidan a un precio de referencia ese día."],["funding-rate","Tasa de financiación (funding rate)","La tasa de financiación es un pago periódico entre traders largos y cortos de futuros perpetuos que mantiene el precio del contrato cerca del precio spot."],["index-price","Precio índice","El precio índice es el precio spot de referencia de un activo que calcula un exchange como media ponderada de los precios de varios exchanges spot."],["funding-rate-arbitrage","Arbitraje de tasa de financiación","El arbitraje de tasa de financiación es una estrategia que combina una posición spot y una posición contraria en futuros perpetuos para cobrar la tasa de financiación sin exponerse a la dirección del precio."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"blockchain-network":{"slug":"blockchain-network","cat":"wallets-security","en":"Deposit network (chain selection)","contentLocale":"es","term":"Red de depósito (selección de red)","aka":["red de retiro","selección de red","red blockchain","network"],"short":"La red de depósito es la blockchain por la que se envía una criptomoneda, y elegirla bien es clave porque el mismo token, como USDT, existe en varias redes que no se comunican entre sí.","body":[["Al retirar o depositar en un exchange, aparece un selector de red: por ejemplo, ",["Ethereum","ethereum"]," (ERC-20), Tron (TRC-20), BNB Smart Chain (BEP-20), Solana, Arbitrum o Polygon. Cada opción es una ",["blockchain","blockchain"]," distinta con sus propias comisiones y tiempos."],["La regla básica es que la red de envío y la de recepción deben coincidir. Si retiras ",["USDT","usdt"]," por Tron, la dirección de destino debe aceptar USDT en Tron. Si no coinciden, los fondos pueden quedar en una red que el destinatario no sigue, y la recuperación, si es posible, suele ser lenta, manual y con costo."],"La elección también afecta al costo. Las comisiones de retiro cambian mucho de una red a otra y de un exchange a otro. Antes de elegir la más barata, comprueba que el destino la admite para ese token concreto."],"example":["Vas a mover 500 USDT de un exchange A a un exchange B. El exchange A ofrece, por ejemplo, Ethereum con 4 USDT de comisión y Tron con 1 USDT. En el exchange B, la página de depósito de USDT muestra Tron y Ethereum, pero tu ",["dirección de depósito","wallet-address"]," cambia según la red. Eliges Tron en ambos lados, pegas la dirección TRC-20 y recibes 499 USDT. Si hubieras elegido Ethereum, habrías recibido 496 USDT. Ahorras 3 USDT sin correr riesgos porque ambas puntas coinciden."],"mistakes":["Elegir la red más barata sin confirmar que el destino acepta ese token en esa red.","Pensar que el nombre del token basta, cuando USDT en Ethereum y USDT en Tron son activos en redes distintas.","No revisar si el exchange tiene suspendidos los depósitos o retiros en una red concreta."],"faq":[{"q":"¿Qué pasa si envío por la red equivocada?","a":"Depende del caso. A veces el exchange puede recuperarlo con una solicitud y una comisión; otras veces los fondos se pierden. Contacta al soporte oficial con el hash de la transacción."},{"q":"¿Qué red es mejor para enviar USDT?","a":"No hay una única respuesta: depende de la comisión, la velocidad y, sobre todo, de que tanto el origen como el destino admitan esa red."}],"title":"¿Qué red elegir al depositar cripto? Selección de red","description":"Qué es la red de depósito o retiro, por qué debe coincidir en origen y destino y cómo elegirla sin perder fondos.","related":[["wallet-address","Dirección de billetera","Una dirección de billetera es la cadena de caracteres que identifica dónde recibir criptomonedas en una red concreta, parecida a un número de cuenta que puedes compartir sin riesgo."],["memo-tag","Memo / Tag de destino","Un memo o tag de destino es un código adicional que algunas redes, como XRP, Stellar, TON o Cosmos, exigen para identificar a qué usuario corresponde un depósito enviado a una dirección compartida."],["gas-fee","Comisión de gas (gas fee)","La comisión de gas (gas fee) es lo que pagas a una blockchain como Ethereum por procesar tu transacción, y depende de cuánto cálculo requiere la operación y de lo congestionada que esté la red."],["withdrawal-fee","Comisión de retiro","La comisión de retiro es el importe que cobra un exchange cuando envías criptomonedas desde tu cuenta a una dirección externa, y suele ser una cantidad fija por cada red."],["transaction-hash","Hash de transacción (TxID)","Un hash de transacción (TxID) es el identificador único de una transacción en la blockchain, que permite buscarla en un explorador de bloques y comprobar su estado."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Antes de transferir: no adivines ninguno de estos puntos"},"coin":null,"tool":null,"cta":false},"mempool":{"slug":"mempool","cat":"onchain","en":"Mempool","contentLocale":"es","term":"Mempool","aka":["memory pool","pool de transacciones pendientes"],"short":"La mempool es la sala de espera de una blockchain: el conjunto de transacciones enviadas que aún no han sido incluidas en un bloque y esperan a ser confirmadas.","body":["Cuando envías una transacción, primero llega a los nodos de la red, que la guardan en su mempool. Los mineros o validadores eligen de ahí qué transacciones incluir en el siguiente bloque, normalmente priorizando las que pagan comisiones más altas.",["Si hay mucha demanda, la mempool se llena y las transacciones con comisiones bajas pueden tardar horas o incluso caducar. En ",["Bitcoin","bitcoin"]," se mide la presión en satoshis por byte virtual (sat/vB); en ",["Ethereum","ethereum"],", en gwei por unidad de gas."],["La mempool también es pública, y eso tiene consecuencias. Bots especializados la vigilan para adelantarse a operaciones grandes en exchanges descentralizados, una práctica asociada al ",["MEV","mev"],". Algunas redes y monederos ofrecen rutas privadas para evitarlo."]],"example":"Supón que envías 0,05 BTC pagando 4 sat/vB, pero la mempool está congestionada y los bloques se llenan con transacciones que pagan 20 sat/vB o más. Tu transacción queda pendiente. Si tu monedero permite subir la comisión (RBF), puedes reenviarla con 22 sat/vB. Para una transacción de 140 vB, la comisión pasa de 560 a 3.080 satoshis, y es probable que entre en uno de los próximos bloques.","mistakes":["Pagar la comisión mínima en plena congestión y esperar una confirmación rápida.","Enviar la misma transacción varias veces pensando que se perdió, cuando solo está en la mempool.","No usar opciones como aumentar la comisión cuando el monedero las ofrece."],"faq":[{"q":"¿Por qué mi transacción está pendiente?","a":"Probablemente sigue en la mempool porque la comisión que pagaste es baja frente a la demanda. Puedes esperar o, si tu monedero lo permite, aumentar la comisión."},{"q":"¿Una transacción puede salir de la mempool sin confirmarse?","a":"Sí. Si pasa demasiado tiempo sin confirmarse, muchos nodos la descartan y los fondos vuelven a estar disponibles en tu monedero."}],"title":"¿Qué es la mempool? Transacciones pendientes","description":"Qué es la mempool, por qué tu transacción queda pendiente y cómo influyen las comisiones en la velocidad de confirmación.","related":[["gas-fee","Comisión de gas (gas fee)","La comisión de gas (gas fee) es lo que pagas a una blockchain como Ethereum por procesar tu transacción, y depende de cuánto cálculo requiere la operación y de lo congestionada que esté la red."],["transaction-hash","Hash de transacción (TxID)","Un hash de transacción (TxID) es el identificador único de una transacción en la blockchain, que permite buscarla en un explorador de bloques y comprobar su estado."],["mev","MEV (valor máximo extraíble)","El MEV, o valor máximo extraíble, es la ganancia que pueden obtener quienes deciden el orden de las transacciones en un bloque, al incluir, excluir o reordenar operaciones de otros usuarios."],["block-confirmations","Confirmaciones de bloque","Las confirmaciones de bloque son el número de bloques añadidos a la blockchain desde que se incluyó una transacción, y cuantas más tiene, más difícil es que se revierta."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"Dice enviado, pero nunca llegó. ¿Dónde debes mirar?"},"coin":null,"tool":null,"cta":false},"no-kyc-exchange":{"slug":"no-kyc-exchange","cat":"regulation","en":"No-KYC exchange","contentLocale":"es","term":"Exchange sin KYC","aka":["exchange no KYC","exchange sin verificación","no-KYC exchange"],"short":"Un exchange sin KYC es una plataforma de intercambio de criptomonedas que permite operar, y a veces retirar, sin verificar tu identidad con documentos, o solo con límites bajos.","body":[["Hay dos grandes grupos. Los exchanges descentralizados (",["DEX","dex"],") no tienen cuentas: conectas tu monedero y operas con contratos inteligentes. Algunos exchanges centralizados permiten abrir cuenta solo con correo y fijan límites de retiro sin verificación, y piden ",["KYC","kyc"]," si superas esos límites o en ciertos productos."],["El atractivo es la privacidad y la rapidez. El coste es la menor protección: si un ",["exchange centralizado","centralized-exchange"]," sin KYC cierra o congela fondos, tienes pocas vías de reclamación. Además, muchos de ellos no tienen licencia en tu país y pueden bloquear el acceso por ubicación."],"Que hoy no pidan KYC no significa que nunca lo hagan. Las políticas cambian, y un exchange puede exigir verificación cuando quieras retirar. Revisa siempre las condiciones y los límites antes de depositar."],"example":["Supón que un exchange centralizado permite retirar hasta el equivalente a 2 ",["BTC","bitcoin"]," al día sin verificación. Depositas 0,5 BTC, operas y acabas con 0,8 BTC. Puedes retirar sin problemas porque estás por debajo del límite. Pero si el exchange cambia su política y reduce el límite sin KYC a 0,1 BTC, tendrías que verificarte para retirar los 0,7 BTC restantes. En un DEX, en cambio, los fondos nunca salen de tu monedero, pero pagas comisiones de gas en cada operación."],"mistakes":["Guardar grandes saldos durante mucho tiempo en un exchange centralizado sin KYC.","Suponer que operar sin KYC te libera de declarar impuestos en tu país.","No leer los términos sobre cuándo el exchange puede exigir verificación."],"faq":[{"q":"¿Es legal usar un exchange sin KYC?","a":"Depende de tu país y de si el exchange está autorizado allí. Muchas jurisdicciones exigen KYC a los proveedores que operan localmente."},{"q":"¿Un DEX es un exchange sin KYC?","a":"En general sí, porque no tiene cuentas y operas desde tu monedero. Aun así, algunas interfaces bloquean direcciones o regiones."}],"title":"¿Qué es un exchange sin KYC? Ventajas y riesgos","description":"Qué es un exchange sin KYC, qué diferencia hay entre DEX y exchanges centralizados sin verificación y qué riesgos asumes.","related":[["kyc","KYC (conoce a tu cliente)","El KYC es el proceso de verificación de identidad que exigen los exchanges y otros servicios regulados para confirmar quién eres antes de dejarte operar o retirar fondos."],["dex","Exchange descentralizado (DEX)","Un exchange descentralizado (DEX) es una plataforma de intercambio de cripto que funciona con contratos inteligentes, donde operas directamente desde tu billetera sin entregar la custodia de tus fondos."],["withdrawal-fee","Comisión de retiro","La comisión de retiro es el importe que cobra un exchange cuando envías criptomonedas desde tu cuenta a una dirección externa, y suele ser una cantidad fija por cada red."],["centralized-exchange","Exchange centralizado (CEX)","Un exchange centralizado (CEX) es una empresa que opera una plataforma donde compras, vendes y operas criptomonedas, custodia tus fondos y empareja las órdenes de los usuarios en su propio libro de órdenes."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"¿Cómo funciona el KYC y a quién debes darle tu documento?"},"coin":null,"tool":"/topics/no-kyc","cta":false},"fiat-on-ramp":{"slug":"fiat-on-ramp","cat":"regulation","en":"Fiat on-ramp","contentLocale":"es","term":"Rampa de entrada fiat (on-ramp)","aka":["on-ramp","rampa fiat","fiat on-ramp","entrada fiat"],"short":"Una rampa de entrada fiat es cualquier servicio que te permite convertir dinero tradicional, como pesos, euros o dólares, en criptomonedas, por ejemplo con transferencia bancaria, tarjeta o P2P.","body":[["Es la puerta de entrada al mundo cripto. Las rampas más comunes son los depósitos bancarios en un exchange, la compra con tarjeta de débito o crédito, los proveedores de pago integrados en monederos y el ",["mercado P2P","p2p-trading"],", donde compras cripto directamente a otros usuarios."],"Cada vía tiene costes y tiempos distintos. La transferencia bancaria suele ser barata pero puede tardar; la tarjeta es inmediata pero con comisiones más altas; el P2P ofrece muchos métodos de pago locales, pero tiene un precio que fija cada anunciante. La rampa de salida (off-ramp) es el camino inverso.",["Casi todas las rampas reguladas exigen ",["KYC","kyc"],". Antes de elegir, compara el precio final que recibes, no solo la comisión anunciada, porque parte del coste puede ir oculto en el tipo de cambio."]],"example":["Supón que quieres ",["convertir","instant-convert"]," el equivalente a 500 USD en ",["USDT","usdt"],". Con tarjeta, la comisión es del 2,5 % y recibes unos 487,50 USDT al instante. Con transferencia bancaria al exchange, sin comisión de depósito, pagas solo un 0,1 % al comprar y recibes unos 499,50 USDT, pero esperas un día. En P2P, un anunciante te vende a 1,01 por USDT: recibes unos 495 USDT pagando por tu método local. La diferencia entre la opción más cara y la más barata es de unos 12 USDT."],"mistakes":["Fijarse solo en la comisión y no en el tipo de cambio aplicado.","Comprar con tarjeta de crédito sin saber que el banco puede tratarlo como adelanto de efectivo.","Usar vías no oficiales para depositar en un exchange porque parecen más rápidas."],"faq":[{"q":"¿Cuál es la forma más barata de comprar cripto con dinero fiat?","a":"Suele ser la transferencia bancaria a un exchange o el P2P con buen precio, pero depende de tu país, tu banco y el exchange. Compara siempre el importe final recibido."},{"q":"¿Qué es un off-ramp?","a":"Es el camino inverso: convertir criptomonedas en dinero tradicional y retirarlo a tu cuenta bancaria o a otro método de pago."}],"title":"¿Qué es una rampa de entrada fiat (on-ramp)?","description":"Qué es una rampa de entrada fiat, qué opciones hay para pasar de dinero tradicional a cripto y cómo comparar su coste real.","related":[["p2p-trading","Trading P2P (C2C)","El trading P2P es la compraventa directa de criptomonedas entre usuarios, donde pagas con transferencia u otros métodos locales y el exchange retiene la cripto en garantía hasta que se confirma el pago."],["kyc","KYC (conoce a tu cliente)","El KYC es el proceso de verificación de identidad que exigen los exchanges y otros servicios regulados para confirmar quién eres antes de dejarte operar o retirar fondos."],["centralized-exchange","Exchange centralizado (CEX)","Un exchange centralizado (CEX) es una empresa que opera una plataforma donde compras, vendes y operas criptomonedas, custodia tus fondos y empareja las órdenes de los usuarios en su propio libro de órdenes."],["stablecoin","Stablecoin (moneda estable)","Una stablecoin es una criptomoneda diseñada para mantener un valor estable frente a un activo de referencia, normalmente el dólar estadounidense, gracias a reservas, garantías en cripto u otros mecanismos."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"Primer depósito: ¿de dónde viene y a dónde va el dinero?"},"coin":null,"tool":null,"cta":true}});
